"""Write a switchback (U-turn) stair spec. Usage: python make_switchback.py out.json [--width 9.5] [--rise 5] [--depth 19] [--cam x,y,z] [--look x,y,z] [--fov 66]
Shaft: x 0..W, far wall at z=-(depth-3), camera side at +z. Flight 1 descends -z along the left wall, mid landing at the far wall, flight 2 returns +z along the right wall."""
import argparse, json
a = argparse.ArgumentParser(); a.add_argument('out'); a.add_argument('--width', type=float, default=9.5); a.add_argument('--rise', type=float, default=5)
a.add_argument('--depth', type=float, default=19); a.add_argument('--cam', default='2.3,5.4,1.0'); a.add_argument('--look', default='5.2,-4.6,-11.0'); a.add_argument('--fov', type=float, default=66)
a.add_argument('--riser', type=float, default=0.58); a.add_argument('--tread', type=float, default=0.92)
o = a.parse_args(); W, R = o.width, o.rise; half = W/2; far = -(o.depth - 3)
n = max(1, round(R/o.riser)); run = n*o.tread; z_bot = -3 - run; land = z_bot - 0.1  # the flight lands 0.1 ft onto the mid landing
spec = {
 "_note": f"Switchback stair, shaft {W} ft wide, two flights of {n} risers, mid landing at the far wall. Generated by make_switchback.py.",
 "camera": {"pos": [float(v) for v in o.cam.split(',')], "look": [float(v) for v in o.look.split(',')], "fov": o.fov},
 "boxes": [
  {"min": [-1, -2*R-2, far-1], "max": [0, 12, 4], "shade": 0.8}, {"min": [W, -2*R-2, far-1], "max": [W+1, 12, 4], "shade": 0.8}, {"min": [0, -2*R-2, far-1], "max": [W, 12, far], "shade": 0.82},
  {"min": [0, -0.6, -3], "max": [half, 0, 3], "shade": 0.7},
  {"min": [0, -R-0.6, far], "max": [W, -R, land], "shade": 0.68},
  {"min": [0, -2*R-0.6, -3], "max": [W, -2*R, 3], "shade": 0.45}],
 "flights": [
  {"name": "flight 1 (down, away)", "start": [0, 0, -3], "dir": "-z", "width": half, "rise": R, "riser": o.riser, "tread": o.tread, "shade": 0.72},
  {"name": "flight 2 (down, back toward camera)", "start": [half, -R, land], "dir": "+z", "width": half, "rise": R, "riser": o.riser, "tread": o.tread, "shade": 0.72}],
 "rails": [
  {"points": [[half-0.2, 3.2, 3], [half-0.2, 3.2, -3], [half-0.2, 3.2-R, land]], "posts": True},
  {"points": [[half-0.2, 3.2-R, land], [half+0.2, 3.2-R, land], [half+0.2, 3.2-2*R, land+run]], "posts": True},
  {"points": [[0.2, 3.0, -2.5], [0.2, 3.0-R, z_bot+0.3]], "posts": False},
  {"points": [[0.3, 3.0-R, far+0.2], [W-0.3, 3.0-R, far+0.2]], "posts": False},
  {"points": [[W-0.2, 3.0-R, land+0.2], [W-0.2, 3.0-2*R, land+run]], "posts": False}],
 "render": {"lights": [{"pos": [1.4, 6.0, -0.5], "i": 150}, {"pos": [W-1.5, 6.2, -3.0], "i": 150}, {"pos": [0.9, 2.0, 0.8], "i": 140}, {"pos": [2.0, -R+3.5, far+3.5], "i": 80}, {"pos": [W-2.1, -R+2.8, -6.5], "i": 150}, {"pos": [half, 0.5, far+1], "i": 50}]}}
json.dump(spec, open(o.out, 'w'), indent=1); print('wrote', o.out, f'{n} risers, run {run:.2f} ft, mid landing z {far}..{land:.2f}')
